package app.noir.mobile;
import android.app.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.List;

/** Shared phone sheet. Callers own actions; the host owns focus, scrolling and dismissal. */
public final class NoirSheet {
 static {Loc.AR.putIfAbsent("Selected","محدد");}
 /** One action tile of a {@link #tiles} grid. `state` (optional) re-reads a toggle after the action ran. */
 public static final class Tile {
  public java.util.function.BooleanSupplier state;public final String icon,label;public final Runnable run;public final boolean enabled;
  public Tile(String icon,String label,Runnable run,boolean enabled){this.icon=icon;this.label=label;this.run=run;this.enabled=enabled;}
 }
 public final Dialog dialog;public final LinearLayout root,body;final Activity activity;final LinearLayout header,footer,titleRow,titles;final ScrollView scroll;final View handle;final View.OnTouchListener drag;TextView name,sub;FrameLayout art;
 int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 TextView text(String value,float size,int color){TextView v=new TextView(activity);v.setText(Loc.t(value));v.setTextSize(size);v.setTextColor(color);return v;}
 GradientDrawable surface(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 public NoirSheet(Activity a,String title,String subtitle){activity=a;dialog=new Dialog(a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);
  root=new LinearLayout(a){@Override protected void onMeasure(int w,int h){super.onMeasure(w,MeasureSpec.makeMeasureSpec((int)(a.getResources().getDisplayMetrics().heightPixels*.86f),MeasureSpec.AT_MOST));}};root.setOrientation(LinearLayout.VERTICAL);root.setTag("noir-sheet");root.setLayoutDirection(Loc.arabic?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);
  GradientDrawable background=surface(0xff161618,0);background.setCornerRadii(new float[]{dp(20),dp(20),dp(20),dp(20),0,0,0,0});background.setStroke(dp(1),0x26ffffff);root.setBackground(background);root.setClipToOutline(true);
  header=new LinearLayout(a);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(20),dp(10),dp(20),dp(PhoneDensity.pick(8,12)));handle=new View(a);handle.setBackground(surface(0xff68656a,2));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(36),dp(4));hp.gravity=Gravity.CENTER_HORIZONTAL;hp.bottomMargin=dp(PhoneDensity.pick(12,16));header.addView(handle,hp);
  titleRow=new LinearLayout(a);titleRow.setGravity(Gravity.CENTER_VERTICAL);titles=new LinearLayout(a);titles.setOrientation(LinearLayout.VERTICAL);titleRow.addView(titles,new LinearLayout.LayoutParams(0,-2,1));header.addView(titleRow);
  name=text(title,PhoneDensity.pick(16,17),0xfff4f1eb);name.setTypeface(null,Typeface.BOLD);if(android.os.Build.VERSION.SDK_INT>=28)name.setAccessibilityHeading(true);titles.addView(name);setSubtitle(subtitle);root.addView(header);
  scroll=new ScrollView(a);scroll.setFillViewport(false);body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),0,dp(16),dp(12));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,-2,1));footer=new LinearLayout(a);footer.setOrientation(LinearLayout.VERTICAL);footer.setPadding(dp(16),dp(8),dp(16),dp(16));footer.setVisibility(View.GONE);root.addView(footer);
  final float[] start={0};drag=(v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){start[0]=e.getRawY();return true;}float dy=Math.max(0,e.getRawY()-start[0]);if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(Motion.enabled(root))root.setTranslationY(dy);return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){if(dy>dp(80))cancel();else{root.setTranslationY(0);v.performClick();}return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL)root.setTranslationY(0);return true;};header.setOnTouchListener(drag);dialog.setContentView(root);dialog.setCanceledOnTouchOutside(true);
 }
 public void setTitle(String value){name.setText(Loc.t(value));}
 public void setSubtitle(String value){if(value==null||value.isEmpty()){if(sub!=null)sub.setVisibility(View.GONE);return;}if(sub==null){sub=text(value,PhoneDensity.pick(12,12.5f),0xff9f9a93);sub.setPadding(0,dp(4),0,0);titles.addView(sub);}sub.setText(Loc.t(value));sub.setVisibility(View.VISIBLE);}
 /** Artwork across the top of the sheet (replaces the drag handle; still drags the sheet down). */
 public FrameLayout art(View content,float heightDp){if(art==null){art=new FrameLayout(activity);art.setOnTouchListener(drag);root.addView(art,0,new LinearLayout.LayoutParams(-1,dp(heightDp)));handle.setVisibility(View.GONE);}art.removeAllViews();art.addView(content,new FrameLayout.LayoutParams(-1,-1));View fade=new View(activity);fade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x50000000,0x00000000,0xff161618}));art.addView(fade,new FrameLayout.LayoutParams(-1,-1));View grip=new View(activity);grip.setBackground(surface(0xaaffffff,2));FrameLayout.LayoutParams gp=new FrameLayout.LayoutParams(dp(36),dp(4),Gravity.TOP|Gravity.CENTER_HORIZONTAL);gp.topMargin=dp(10);art.addView(grip,gp);header.setPadding(dp(20),dp(2),dp(20),dp(PhoneDensity.pick(8,12)));return art;}
 /** A ✕ in the title row (or over the artwork). Back, dragging down and tapping outside also close the sheet. */
 public View closeButton(String description){TextView x=text("✕",PhoneDensity.pick(16,18),0xffc7c2bc);x.setGravity(Gravity.CENTER);x.setContentDescription(Loc.t(description));x.setFocusable(true);x.setOnClickListener(v->cancel());if(art!=null){x.setBackground(surface(0xc80c0c0e,22));FrameLayout.LayoutParams xp=new FrameLayout.LayoutParams(dp(44),dp(44),Gravity.TOP|Gravity.END);xp.setMargins(dp(10),dp(8),dp(10),0);art.addView(x,xp);}else titleRow.addView(x,new LinearLayout.LayoutParams(dp(44),dp(44)));return x;}
 public View row(String icon,String label,String hint,boolean enabled,String disabledReason,Runnable action){LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(PhoneDensity.pick(48,52)));row.setPadding(dp(4),dp(PhoneDensity.pick(8,10)),dp(4),dp(PhoneDensity.pick(8,10)));TextView glyph=text(icon,PhoneDensity.pick(18,20),0xffe4c084);glyph.setGravity(Gravity.CENTER);glyph.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);row.addView(glyph,new LinearLayout.LayoutParams(dp(36),dp(32)));LinearLayout info=new LinearLayout(activity);info.setOrientation(LinearLayout.VERTICAL);info.setPaddingRelative(dp(10),0,dp(4),0);info.addView(text(label,PhoneDensity.pick(14.5f,15),0xfff4f1eb));String detail=enabled?hint:disabledReason;if(detail!=null&&!detail.isEmpty())info.addView(text(detail,PhoneDensity.pick(11.5f,12),0xff9f9a93));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.setAlpha(enabled?1:.45f);row.setFocusable(true);row.setContentDescription(Loc.t(label)+(detail==null||detail.isEmpty()?"":" · "+Loc.t(detail)));row.setTag(label);row.setOnClickListener(v->{if(enabled&&action!=null)action.run();});body.addView(row);return row;}
 /** A row that closes the sheet, then runs its action (menus). */
 public View action(String icon,String label,String hint,Runnable action){return row(icon,label,hint,true,null,()->{dismiss();if(action!=null)action.run();});}
 /** A list choice: closes the sheet, then runs the action. A gold ✓ marks the current one. */
 public View choice(String label,String hint,boolean selected,Runnable action){View row=row(selected?"✓":"",label,hint,true,null,()->{dismiss();if(action!=null)action.run();});if(selected)row.setContentDescription(row.getContentDescription()+" · "+Loc.t("Selected"));return row;}
 /** A quiet single-line action; dismisses first when `close` is set. */
 public TextView link(String label,boolean gold,boolean close,Runnable action){TextView v=text(label,PhoneDensity.pick(14,14.5f),gold?0xffe4c084:0xffc7c2bc);v.setGravity(Gravity.CENTER_VERTICAL);v.setMinHeight(dp(PhoneDensity.pick(44,48)));v.setPadding(dp(4),dp(6),dp(4),dp(6));v.setFocusable(true);v.setContentDescription(Loc.t(label));v.setOnClickListener(w->{if(close)dismiss();if(action!=null)action.run();});body.addView(v);return v;}
 public TextView note(String value){TextView v=text(value,PhoneDensity.pick(13,13.5f),0xff9f9a93);v.setLineSpacing(dp(2),1);v.setPadding(dp(4),dp(4),dp(4),dp(8));body.addView(v);return v;}
 public void section(String label){TextView v=text(label,10,0xff9f9a93);v.setLetterSpacing(.12f);v.setTypeface(null,Typeface.BOLD);v.setPadding(dp(4),dp(PhoneDensity.pick(14,18)),0,dp(6));if(android.os.Build.VERSION.SDK_INT>=28)v.setAccessibilityHeading(true);body.addView(v);}
 public View busy(String label){LinearLayout line=new LinearLayout(activity);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(4),dp(8),dp(4),dp(12));ProgressBar spinner=new ProgressBar(activity);spinner.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(0xffe4c084));line.addView(spinner,new LinearLayout.LayoutParams(dp(22),dp(22)));TextView t=text(label,13.5f,0xffc7c2bc);t.setPaddingRelative(dp(12),0,0,0);line.addView(t);line.setContentDescription(Loc.t(label));body.addView(line);return line;}
 /** Action tiles in a tidy grid. A toggle tile (state != null) refreshes its glyph after its action. */
 public void tiles(int columns,List<Tile> actions){for(int n=0;n<actions.size();n+=columns){LinearLayout line=new LinearLayout(activity);line.setGravity(Gravity.TOP);body.addView(line);for(int k=0;k<columns;k++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));if(n+k>=actions.size()){line.addView(new View(activity),p);continue;}Tile action=actions.get(n+k);LinearLayout tile=new LinearLayout(activity);tile.setOrientation(LinearLayout.VERTICAL);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(6),dp(PhoneDensity.pick(9,12)),dp(6),dp(PhoneDensity.pick(9,12)));tile.setMinimumHeight(dp(PhoneDensity.pick(72,88)));tile.setBackground(surface(0xff1a1a1d,14));TextView glyph=text(action.icon,PhoneDensity.pick(21,24),0xffe4c084);glyph.setGravity(Gravity.CENTER);glyph.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);tile.addView(glyph);TextView label=text(action.label,PhoneDensity.pick(11.5f,12),0xfff4f1eb);label.setGravity(Gravity.CENTER);label.setPadding(0,dp(5),0,0);tile.addView(label);tile.setEnabled(action.enabled);tile.setAlpha(action.enabled?1:.4f);tile.setFocusable(action.enabled);tile.setContentDescription(Loc.t(action.label));tile.setOnClickListener(v->{action.run.run();if(action.state!=null){glyph.setText(action.state.getAsBoolean()?"✓":"＋");Motion.haptic(tile);}Motion.pop(tile);});line.addView(tile,p);}}}
 public CheckBox check(String label,boolean checked,CompoundButton.OnCheckedChangeListener listener){CheckBox v=new CheckBox(activity);v.setText(Loc.t(label));v.setTextColor(0xffc7c2bc);v.setTextSize(13);v.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffe4c084));v.setMinHeight(dp(48));v.setContentDescription(Loc.t(label));v.setChecked(checked);v.setOnCheckedChangeListener(listener);body.addView(v);return v;}
 public <T extends View> T add(T view){body.addView(view);return view;}
 // Footer button that keeps the sheet open (forms that validate before closing call dismiss() themselves).
 public View footerKeepOpen(String label,Runnable action,boolean primary){View v=button(label,null,primary);v.setOnClickListener(w->{if(action!=null)action.run();});footer.setVisibility(View.VISIBLE);footer.addView(v);return v;}
 public void footer(String primary,Runnable action,String secondary,Runnable other){footer.removeAllViews();if(primary!=null&&!primary.isEmpty())footer.addView(button(primary,action,true));if(secondary!=null&&!secondary.isEmpty())footer.addView(button(secondary,other,false));footer.setVisibility(footer.getChildCount()>0?View.VISIBLE:View.GONE);}
 /** The one primary action, pinned under the list; `description` is what talkback and tests read. */
 public View footerPrimary(String label,String description,Runnable action){footer.removeAllViews();View v=button(label,action,true);if(description!=null)v.setContentDescription(Loc.t(description));footer.addView(v);footer.setVisibility(View.VISIBLE);return v;}
 View button(String label,Runnable action,boolean primary){TextView v=text(label,PhoneDensity.pick(13.5f,14),primary?0xff0b0b0d:0xffc7c2bc);v.setGravity(Gravity.CENTER);v.setTypeface(null,Typeface.BOLD);v.setBackground(surface(primary?0xffe4c084:0x00161618,12));v.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(PhoneDensity.pick(42,44))));v.setContentDescription(Loc.t(label));v.setFocusable(true);v.setOnClickListener(w->{dismiss();if(action!=null)action.run();});return v;}
 public void show(){if(activity.isFinishing()||activity.isDestroyed())return;dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams p=w.getAttributes();p.width=Math.min(activity.getResources().getDisplayMetrics().widthPixels,dp(560));p.height=WindowManager.LayoutParams.WRAP_CONTENT;p.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;p.dimAmount=.6f;p.windowAnimations=0;w.setAttributes(p);}root.post(()->{if(Motion.enabled(root)){root.setTranslationY(root.getHeight());root.animate().translationY(0).setDuration(180).start();}View focus=body.getChildCount()>0?body.getChildAt(0):header;focus.requestFocus();});}
 public void dismiss(){root.animate().cancel();dialog.dismiss();}
 // The user backing out (✕, drag down): like Back, runs the dialog's OnCancelListener so pending work (e.g. a stream search) stops.
 public void cancel(){root.animate().cancel();dialog.cancel();}
}
